text:
The patch changes the pluralization boundary in `plural` from `msAbs >= n * 1.5` to strictly greater. At the exact boundary (e.g. 1500 ms, 1.5 minutes, 1.5 hours, 1.5 days), the long formatter previously returned the plural form (`Math.round(1.5)` is 2, and `>=` made `isPlural` true), while the patched build returns the singular form. For example, `ms(1500, { long: true })` was `'2 seconds'` and is now `'2 second'` — an observable difference for callers using the `long` option (the short formatter is unaffected, which is why the existing suite still passes).

```json
{"defect": true, "testFile": {"path": "proof-test.js", "content": "var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Exactly 1.5 units: the reference behaviour pluralizes (msAbs >= n * 1.5)
    assert.strictEqual(ms(1500, { long: true }), '2 seconds');
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
    assert.strictEqual(ms(5400000, { long: true }), '2 hours');
    assert.strictEqual(ms(129600000, { long: true }), '2 days');
  });
});
"}, "note": "The change from `msAbs >= n * 1.5` to `msAbs > n * 1.5` alters long formatting at the exact 1.5-unit boundary: e.g. ms(1500, {long:true}) returns '2 second' instead of '2 seconds'. The default test suite never hits this exact boundary, so it stays green despite the regression."}
```

